import os, glob, re, html
from datetime import datetime

LEVELDB_DIR = r"C:\Users\PC\AppData\Roaming\RingCentral\IndexedDB\https_app.ringcentral.com_0.indexeddb.leveldb"
OUTPUT_FILE = r"E:\Job\ChiDao_Manager_Moi.md"

def clean_html(raw_html):
    clean_text = re.sub(r'<[^>]+>', ' ', raw_html)
    clean_text = html.unescape(clean_text)
    clean_text = re.sub(r'\s+', ' ', clean_text).strip()
    return clean_text

def extract_manager_knowledge():
    files = glob.glob(os.path.join(LEVELDB_DIR, "*.log")) + glob.glob(os.path.join(LEVELDB_DIR, "*.ldb"))
    files.sort(key=os.path.getmtime, reverse=True)

    print(f"Scanning all {len(files)} RingCentral cache files...")
    
    target_groups = ["Manager Team", "group manager support+Wendy", "Tam Phan", "Khanh Nguyen"]
    leaders = ["Phuc Trinh", "Wendy Vo", "Cristy Trinh", "Tam Phan", "Andy Vo", "Jasmine Tang", "Eric", "Saphia", "Ha To", "Khanh Nguyen"]
    
    found_snippets = []
    seen = set()

    pattern = re.compile(rb'text\"[\x00-\xff]{1,3}([\x20-\x7E\xC2-\xF4\x80-\xBF]{8,1000})\"')

    for fpath in files[:35]:
        try:
            with open(fpath, "rb") as f:
                data = f.read()
            
            for m in pattern.finditer(data):
                try:
                    raw_txt = m.group(1).decode('utf-8', errors='ignore').strip()
                    cleaned_txt = clean_html(raw_txt)
                    
                    if len(cleaned_txt) > 10 and cleaned_txt not in seen:
                        if cleaned_txt.startswith('{') or cleaned_txt.startswith('http') or 'prototype' in cleaned_txt or 'webpack' in cleaned_txt or 'at_mention' in cleaned_txt:
                            continue
                        
                        ctx = data[max(0, m.start()-400):min(len(data), m.end()+400)]
                        
                        matched_group = None
                        if b"Manager Team" in ctx or b"coaching her" in ctx or b"Tara" in ctx:
                            matched_group = "Manager Team"
                        elif b"support+Wendy" in ctx or b"manager support" in ctx.lower() or b"Collect Information" in ctx or b"m\xc3\xa3 s\xe1\xbb\x91 b\xc6\xb0u" in ctx:
                            matched_group = "group manager support+Wendy"
                        elif b"Tam Phan" in ctx or b"Ha To" in ctx or b"consent form cho Ha To" in ctx:
                            matched_group = "Tam Phan (Direct Message / Chỉ Đạo Nóng)"
                        elif b"Khanh Nguyen" in ctx or b"sep moi co the xanh" in ctx:
                            matched_group = "Agent Support (Khanh Nguyen - Case IL)"
                        
                        matched_author = None
                        for leader in leaders:
                            if leader.lower().encode() in ctx.lower():
                                matched_author = leader
                                break
                        
                        if matched_group or matched_author:
                            seen.add(cleaned_txt)
                            grp_name = matched_group if matched_group else "Manager Discussion"
                            auth_name = matched_author if matched_author else "Manager / Team"
                            found_snippets.append({
                                "group": grp_name,
                                "author": auth_name,
                                "text": cleaned_txt
                            })
                except Exception:
                    pass
        except Exception:
            pass

    print(f"Extracted {len(found_snippets)} messages from Manager groups & DMs!")
    
